/*
 * Function contract: accepts one message from cold-chain/+/telemetry and returns
 * six output slots in the order wired below: temperature gauge, humidity gauge,
 * temperature chart, humidity chart, door indicator, and local alarm formatter.
 * Invalid JSON or required fields are warned and dropped with no state updates.
 * Per-device context remembers the last thermal state, door-open arrival time,
 * and whether the 30-second door alarm has already fired. The device alarm MQTT
 * input uses a separate formatter; local alarms route directly to that formatter
 * to avoid publishing them back to MQTT and creating an echo loop.
 */
let p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (error) {
        node.warn('Invalid MQTT JSON: ' + error.message);
        return null;
    }
}
const id = p && (p.device_id || msg.topic.split('/')[1]);
if (!id || !Number.isFinite(p.temperature_c) || !Number.isFinite(p.humidity_pct) || typeof p.door_open !== 'boolean') {
    node.warn('Invalid telemetry on ' + msg.topic);
    return null;
}
const now = Date.now();
// Build the dashboard fan-out in the exact order of this Function node's six wires.
const out = [
    { payload: p.temperature_c },
    { payload: p.humidity_pct },
    { payload: p.temperature_c, topic: id },
    { payload: p.humidity_pct, topic: id },
    { payload: p.door_open ? 'OPEN' : 'CLOSED' },
    null
];
// Detect only thermal state transitions so each excursion and restoration is emitted once.
const alarms = [];
const temperatureOutOfRange = p.temperature_c < 2 || p.temperature_c > 8;
const wasOutOfRange = context.get('temperatureAlarm:' + id) === true;
if (temperatureOutOfRange && !wasOutOfRange) {
    alarms.push({ code: 'temperature_excursion', message: 'Temperature outside the 2 to 8 C range', value: p.temperature_c });
} else if (!temperatureOutOfRange && wasOutOfRange) {
    alarms.push({ code: 'temperature_restored', message: 'Temperature returned to the 2 to 8 C range', value: p.temperature_c });
}
context.set('temperatureAlarm:' + id, temperatureOutOfRange);
// Measure door duration from the first telemetry message observed with the door open.
let doorOpenedAt = context.get('doorOpenedAt:' + id);
if (p.door_open) {
    if (!doorOpenedAt) {
        doorOpenedAt = now;
        context.set('doorOpenedAt:' + id, doorOpenedAt);
    }
    // Emit once after the limit; subsequent open samples do not duplicate this alarm.
    if (now - doorOpenedAt >= 30000 && context.get('doorAlarm:' + id) !== true) {
        alarms.push({ code: 'door_open_too_long', message: 'Door has been open for more than 30 seconds' });
        context.set('doorAlarm:' + id, true);
    }
} else {
    // A closed-door sample clears both pieces of state for the next opening cycle.
    context.set('doorOpenedAt:' + id, null);
    context.set('doorAlarm:' + id, false);
}
// Attach all locally detected alarms to output six; Node-RED fans out each array item.
if (alarms.length > 0) {
    out[5] = alarms.map(alarm => ({
        payload: { device_id: id, ...alarm, timestamp: new Date(now).toISOString() }
    }));
}
return out;

/*
 * Function contract: accepts either an object or JSON string from an alarm input.
 * It validates the fields used by the dashboard, warns and drops invalid messages,
 * then replaces msg.payload with one concise code/message string and returns the
 * same message object. Its incoming wires are device MQTT alarms and locally
 * generated alarms from validate-and-route; its output feeds the latest-alarm
 * dashboard widget, so this formatter never republishes an event to MQTT.
 */
let event = msg.payload;
if (typeof event === 'string') {
    try { event = JSON.parse(event); } catch (error) {
        node.warn('Invalid alarm event: ' + error.message);
        return null;
    }
}
if (!event || !event.code || !event.message) {
    node.warn('Alarm event is missing its code or message');
    return null;
}
// Normalize both device and backend alarm payloads for the dashboard text widget.
msg.payload = event.code + ': ' + event.message;
return msg;
